import React, { useState, useEffect } from 'react';
import { Chart } from 'react-google-charts';
import axios from 'axios';
import { useNavigate } from 'react-router-dom';
import './Visualization.css';  // Reuse landing page styles
import backgroundImage from '../assets/background.jpg';
import sunIcon from '../assets/sun.png';
import moonIcon from '../assets/moon.png';

function Visualization() {
  const navigate = useNavigate();

  const [columns, setColumns] = useState([]);
  const [selectedX, setSelectedX] = useState('');
  const [selectedY, setSelectedY] = useState('');
  const [chartType, setChartType] = useState('ScatterChart');
  const [data, setData] = useState([]);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');
  const [darkMode, setDarkMode] = useState(false);

  useEffect(() => {
    document.body.className = darkMode ? 'dark-mode' : 'light-mode';
  }, [darkMode]);

  useEffect(() => {
    const fetchColumns = async () => {
      try {
        const response = await axios.get('http://localhost:8000/data/columns');
        if (response.data.columns && response.data.columns.length >= 2) {
          setColumns(response.data.columns);
          setSelectedX(response.data.columns[0]);
          setSelectedY(response.data.columns[1]);
          setError('');
        } else {
          setError('No columns available for visualization');
        }
      } catch (err) {
        setError('Failed to load column information');
        console.error(err);
      }
    };
    fetchColumns();
  }, []);

  const generateChart = async () => {
    if (!selectedX || !selectedY) {
      setError('Please select both X and Y axes');
      setData([]);
      return;
    }
    setIsLoading(true);
    setError('');
    try {
      const response = await axios.get('http://localhost:8000/data/sample', {
        params: { x: selectedX, y: selectedY, limit: 100 },
      });
      if (!response.data || response.data.length === 0) {
        setError('No data available for selected columns');
        setData([]);
        setIsLoading(false);
        return;
      }
      const chartData = [
        [selectedX, selectedY],
        ...response.data.map(item => [item[selectedX], item[selectedY]]),
      ];
      setData(chartData);
      setError('');
    } catch (err) {
      setError('Failed to generate chart');
      setData([]);
      console.error(err);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    if (selectedX && selectedY) {
      generateChart();
    }
  }, [selectedX, selectedY]);

  return (
    <div
      className="landing-wrapper"
      style={{ backgroundImage: `url(${backgroundImage})` }}
    >
      {darkMode && <div className="dark-overlay" />}
      <div className="glass-card">
        <div className="header">
          <h1>Data Visualization</h1>
          <button
            className="toggle-btn"
            onClick={() => setDarkMode(!darkMode)}
            aria-label="Toggle theme"
          >
            <img
              src={darkMode ? sunIcon : moonIcon}
              alt="Toggle theme"
              className="theme-icon"
            />
          </button>
        </div>
        <p className="tagline">Explore your data interactively.</p>

        <div className="button-container" style={{ justifyContent: 'center', marginBottom: '1rem' }}>
          <button onClick={() => navigate('/')}>🏠 Home</button>
          <button onClick={() => navigate('/prediction')}>🧬 Prediction</button>
        </div>

        <div className="controls" style={{ marginBottom: '1rem', color: darkMode ? '#f0f0f0' : '#1a1a1a' }}>
          <label htmlFor="xAxisSelect">X-Axis:</label>
          <select
            id="xAxisSelect"
            value={selectedX}
            onChange={e => setSelectedX(e.target.value)}
            disabled={isLoading}
            style={{ marginLeft: 8, padding: '0.4rem', borderRadius: 8, border: 'none' }}
          >
            <option value="">Select column</option>
            {columns.map(col => (
              <option key={col} value={col}>
                {col}
              </option>
            ))}
          </select>

          <label htmlFor="yAxisSelect" style={{ marginLeft: 16 }}>Y-Axis:</label>
          <select
            id="yAxisSelect"
            value={selectedY}
            onChange={e => setSelectedY(e.target.value)}
            disabled={isLoading}
            style={{ marginLeft: 8, padding: '0.4rem', borderRadius: 8, border: 'none' }}
          >
            <option value="">Select column</option>
            {columns.map(col => (
              <option key={col} value={col}>
                {col}
              </option>
            ))}
          </select>

          <label htmlFor="chartTypeSelect" style={{ marginLeft: 16 }}>Chart Type:</label>
          <select
            id="chartTypeSelect"
            value={chartType}
            onChange={e => setChartType(e.target.value)}
            disabled={isLoading}
            style={{ marginLeft: 8, padding: '0.4rem', borderRadius: 8, border: 'none' }}
          >
            <option value="ScatterChart">Scatter Chart</option>
            <option value="LineChart">Line Chart</option>
            <option value="BarChart">Bar Chart</option>
            <option value="Histogram">Histogram</option>
          </select>
        </div>

        {error && <div className="error-message" style={{ color: 'red' }}>{error}</div>}

        <div className="chart-container" style={{ color: darkMode ? '#f0f0f0' : '#1a1a1a' }}>
          {isLoading ? (
            <div className="loading">Loading chart data...</div>
          ) : data && Array.isArray(data) && data.length > 1 ? (
            <Chart
              chartType={chartType}
              width="100%"
              height="400px"
              data={data}
              options={{
                title: `${selectedY} vs ${selectedX}`,
                hAxis: { title: selectedX, textStyle: { color: darkMode ? '#f0f0f0' : '#1a1a1a' } },
                vAxis: { title: selectedY, textStyle: { color: darkMode ? '#f0f0f0' : '#1a1a1a' } },
                legend: { position: 'none' },
                chartArea: { width: '80%', height: '70%' },
                backgroundColor: 'transparent',
                titleTextStyle: { color: darkMode ? '#f0f0f0' : '#1a1a1a' },
                tooltip: { textStyle: { color: darkMode ? '#f0f0f0' : '#1a1a1a' } },
              }}
            />
          ) : (
            <div className="no-data">
              {columns.length > 0
                ? 'Select columns to generate chart'
                : 'Loading columns...'}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

export default Visualization;
